// ENTRADA → PROCESSAMENTO: unifica formulário e webhook, valida, gera o protocolo
// e mascara dados sensíveis antes de qualquer texto sair para o LLM.
// ---- utilitários compartilhados (incluídos pelo gerador nos nós Code que precisam) ----
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const paragrafos = (t) => String(t ?? '').trim().split(/\n{2,}/)
  .map((p) => `<p style="margin:0 0 14px">${esc(p).replace(/\n/g, '<br>')}</p>`).join('');
const emailHtml = ({ titulo, corpo, protocolo }) => `<!doctype html><html lang="pt-BR"><body style="margin:0;background:#f3f5f9;font-family:Segoe UI,Helvetica,Arial,sans-serif;color:#1f2937">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:24px 12px"><tr><td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:10px;overflow:hidden;border:1px solid #e3e7ef">
<tr><td style="background:#1d3b8b;color:#ffffff;padding:18px 24px;font-size:17px;font-weight:600">Vértice Cloud · Atendimento</td></tr>
<tr><td style="padding:24px 24px 8px;font-size:15px;line-height:1.55">
<p style="margin:0 0 14px;font-size:17px;font-weight:600">${esc(titulo)}</p>${corpo}</td></tr>
<tr><td style="padding:8px 24px 22px;font-size:12px;color:#6b7280">Protocolo <strong style="color:#1f2937">${esc(protocolo)}</strong> · guarde este número para acompanhar sua solicitação.</td></tr>
</table></td></tr></table></body></html>`;
const fmtData = (iso) => new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const brl = (n) => (n == null || Number.isNaN(Number(n))) ? 'não informado' : Number(n).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const j = $input.item.json;
const b = j.body && typeof j.body === 'object' ? j.body : j;
const veioDoWebhook = j.body && typeof j.body === 'object';
const pick = (...ks) => {
  for (const k of ks) if (b[k] !== undefined && b[k] !== null && String(b[k]).trim() !== '') return String(b[k]).trim();
  return '';
};

const nome = pick('nome', 'Nome').slice(0, 120);
const email = pick('email', 'E-mail', 'Email').toLowerCase().slice(0, 160);
const canalBruto = pick('canal', 'Canal').toLowerCase();
const canal = { portal: 'portal', 'e-mail': 'email', email: 'email', whatsapp: 'whatsapp', api: 'api' }[canalBruto] ?? (veioDoWebhook ? 'api' : 'portal');
const assunto = pick('assunto', 'Assunto').slice(0, 200);
const mensagem = pick('mensagem', 'Mensagem').slice(0, 4000);

const erros = [];
if (!nome) erros.push('nome ausente');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) erros.push('e-mail inválido');
if (!assunto) erros.push('assunto ausente');
if (mensagem.length < 10) erros.push('mensagem muito curta (mínimo 10 caracteres)');

// Minimização de dados (LGPD): CNPJ → cartão → CPF, nessa ordem para um padrão não "comer" o outro.
const mascarar = (t) => t
  .replace(/\b\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}\b/g, '[CNPJ]')
  .replace(/\b(?:\d[ -]?){13,19}\b/g, '[CARTAO]')
  .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF]');

const agora = new Date();
const data = agora.toISOString().slice(0, 10).replace(/-/g, '');
const sufixo = Array.from({ length: 5 }, () => 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[Math.floor(Math.random() * 32)]).join('');
const protocolo = `DEM-${data}-${sufixo}`;

const primeiro_nome = nome.split(/\s+/)[0] ?? '';
const corpoAck = paragrafos(
  `Olá, ${primeiro_nome}!\n\nRecebemos a sua solicitação "${assunto}" e ela já está sendo analisada pela nossa equipe. Você receberá uma resposta neste mesmo e-mail.`
);

return {
  json: {
    valido: erros.length === 0,
    erros,
    protocolo,
    canal,
    nome,
    primeiro_nome,
    email,
    assunto,
    mensagem,
    assunto_mascarado: mascarar(assunto),
    mensagem_mascarada: mascarar(mensagem),
    recebido_em: agora.toISOString(),
    email_ack_assunto: `[${protocolo}] Recebemos sua solicitação`,
    email_ack_html: emailHtml({ titulo: 'Recebemos a sua solicitação', corpo: corpoAck, protocolo }),
  },
};

