// DECISÃO: regras de negócio DETERMINÍSTICAS aplicadas sobre a saída da IA.
// A IA classifica e recomenda; quem decide o que pode ser automático é este nó.
const entrada = $input.item.json;
const triagem = entrada.output ?? {};
const iaFalhou = entrada.ia_falhou === true;
const base = $('Normalizar e validar').first().json;
const ctx = $('Registrar demanda e carregar contexto').first().json;
const cfg = $('Parâmetros de negócio').first().json;

const CATEGORIAS = ['cobranca', 'reembolso', 'cancelamento', 'incidente_tecnico', 'duvida_tecnica', 'comercial', 'elogio_sugestao', 'outros'];
const ORDEM = ['P1', 'P2', 'P3', 'P4'];
const EQUIPES = {
  cobranca: 'Financeiro',
  reembolso: 'Financeiro',
  cancelamento: 'Customer Success',
  incidente_tecnico: 'Suporte N2 / Plantão',
  duvida_tecnica: 'Suporte N1',
  comercial: 'Vendas',
  elogio_sugestao: 'Customer Success',
  outros: 'Triagem manual',
};
const SLA_BASE_H = { P1: 1, P2: 4, P3: 8, P4: 24 };
const SLA_MULT = { enterprise: 0.5, pro: 1, starter: 1.5 };

const limiteAprovacao = Number(cfg.limite_aprovacao_brl);
const confMinima = Number(cfg.confianca_minima);
const confAuto = Number(cfg.confianca_auto);
const categoriasAuto = String(cfg.categorias_auto).split(',').map((s) => s.trim());

const categoria = CATEGORIAS.includes(triagem.categoria) ? triagem.categoria : 'outros';
const confianca = iaFalhou ? 0 : Math.max(0, Math.min(1, Number(triagem.confianca ?? 0)));
const valorBruto = Number(triagem.valor_envolvido_brl);
const valor = Number.isFinite(valorBruto) && valorBruto > 0 ? valorBruto : null; // 0 = sem valor citado
const plano = ctx.plano ?? null;
const ajustes = [];

// Prioridade: parte do que a IA sugeriu, mas com pisos fixos (o texto do cliente não pode "rebaixar" o que é grave).
let prioridade = ORDEM.includes(triagem.prioridade) ? triagem.prioridade : 'P3';
const prioridadeIA = prioridade;
const subir = (p, ate) => (ORDEM.indexOf(p) > ORDEM.indexOf(ate) ? ate : p);
if (categoria === 'incidente_tecnico') prioridade = subir(prioridade, 'P2');
if (plano === 'enterprise') prioridade = subir(prioridade, 'P3');
if (plano === 'enterprise' && ['negativo', 'critico'].includes(triagem.sentimento) && ORDEM.indexOf(prioridade) > 1) {
  prioridade = ORDEM[ORDEM.indexOf(prioridade) - 1];
}
if (prioridade !== prioridadeIA) ajustes.push(`prioridade ${prioridadeIA} → ${prioridade} por regra de negócio`);

// Quando exigir aprovação humana (ação crítica ou risco).
const motivos = [];
if (['reembolso', 'cancelamento'].includes(categoria)) motivos.push(`Ação financeira/contratual: ${categoria}`);
const moeda = (n) => Number(n).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
if (valor != null && valor >= limiteAprovacao) motivos.push(`Valor ${moeda(valor)} ≥ limite de ${moeda(limiteAprovacao)}`);
if (triagem.risco_juridico_ou_reputacional === true) motivos.push('Risco jurídico ou reputacional');
if (plano === 'enterprise' && prioridade === 'P1') motivos.push('Cliente Enterprise com demanda P1');
const exigeAprovacao = motivos.length > 0;

// Modo de tratamento
let modo;
if (iaFalhou) {
  modo = 'encaminhar';
  motivos.push('IA indisponível: triagem manual');
} else if (exigeAprovacao) {
  modo = 'aprovacao';
} else if (confianca < confMinima) {
  modo = 'aprovacao';
  motivos.push(`Baixa confiança da IA (${confianca.toFixed(2)} < ${confMinima.toFixed(2)}): revisar classificação`);
} else if (
  categoriasAuto.includes(categoria) &&
  confianca >= confAuto &&
  triagem.resposta_automatica_segura === true &&
  ['P3', 'P4'].includes(prioridade) &&
  ctx.status_cliente !== 'inadimplente'
) {
  modo = 'auto';
} else {
  modo = 'encaminhar';
}

const fatorSla = SLA_MULT[plano] ?? 1.5;
const slaHoras = SLA_BASE_H[prioridade] * fatorSla;
const slaLimite = new Date(Date.now() + slaHoras * 3600 * 1000).toISOString();

return {
  json: {
    protocolo: base.protocolo,
    categoria,
    prioridade,
    prioridade_ia: prioridadeIA,
    sentimento: triagem.sentimento ?? 'neutro',
    resumo: String(triagem.resumo ?? (iaFalhou ? 'Triagem automática indisponível; ler a mensagem original.' : '')).slice(0, 300),
    valor_envolvido_brl: valor,
    confianca,
    justificativa: String(triagem.justificativa ?? ''),
    risco_juridico: triagem.risco_juridico_ou_reputacional === true,
    resposta_automatica_segura: triagem.resposta_automatica_segura === true,
    ia_falhou: iaFalhou,
    modo,
    exige_aprovacao: exigeAprovacao || modo === 'aprovacao',
    motivos,
    ajustes,
    equipe: EQUIPES[categoria],
    sla_horas: slaHoras,
    sla_limite: slaLimite,
    // contexto repassado adiante
    nome: base.nome,
    primeiro_nome: base.primeiro_nome,
    email: base.email,
    assunto: base.assunto,
    mensagem_mascarada: base.mensagem_mascarada,
    plano: plano ?? 'não cadastrado',
    status_cliente: ctx.status_cliente ?? 'não cadastrado',
    empresa: ctx.empresa ?? '',
    sessao_id: ctx.sessao_id,
  },
};

// DECISÃO (2/2): guardrail determinístico sobre o TEXTO que a IA escreveu e consolidação do estado
// que os ramos seguintes usam. Se a resposta automática violar uma regra, ela é rebaixada para
// "encaminhar": o rascunho vira só uma sugestão para o atendente.
// ---- utilitários compartilhados (incluídos pelo gerador nos nós Code que precisam) ----
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const paragrafos = (t) => String(t ?? '').trim().split(/\n{2,}/)
  .map((p) => `<p style="margin:0 0 14px">${esc(p).replace(/\n/g, '<br>')}</p>`).join('');
const emailHtml = ({ titulo, corpo, protocolo }) => `<!doctype html><html lang="pt-BR"><body style="margin:0;background:#f3f5f9;font-family:Segoe UI,Helvetica,Arial,sans-serif;color:#1f2937">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:24px 12px"><tr><td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:10px;overflow:hidden;border:1px solid #e3e7ef">
<tr><td style="background:#1d3b8b;color:#ffffff;padding:18px 24px;font-size:17px;font-weight:600">Vértice Cloud · Atendimento</td></tr>
<tr><td style="padding:24px 24px 8px;font-size:15px;line-height:1.55">
<p style="margin:0 0 14px;font-size:17px;font-weight:600">${esc(titulo)}</p>${corpo}</td></tr>
<tr><td style="padding:8px 24px 22px;font-size:12px;color:#6b7280">Protocolo <strong style="color:#1f2937">${esc(protocolo)}</strong> · guarde este número para acompanhar sua solicitação.</td></tr>
</table></td></tr></table></body></html>`;
const fmtData = (iso) => new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const brl = (n) => (n == null || Number.isNaN(Number(n))) ? 'não informado' : Number(n).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const entrada = $input.item.json;
const r = $('Regras de negócio').first().json;
const redatorFalhou = entrada.redator_falhou === true;

const rascunhoIA = String(entrada.output ?? '').trim();
const rascunho = rascunhoIA || `Olá, ${r.primeiro_nome}!\n\nRecebemos a sua solicitação e nossa equipe já está analisando. Retornaremos em breve, neste mesmo e-mail.\n\nEquipe de Atendimento Vértice Cloud`;

const alertas = [];
if (redatorFalhou || !rascunhoIA) alertas.push('Redator indisponível: usado texto padrão');
if (rascunho.length > 1800) alertas.push('rascunho muito longo');
if (/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/.test(rascunho)) alertas.push('possível CPF no texto');
if (/\b(?:\d[ -]?){13,19}\b/.test(rascunho)) alertas.push('possível número de cartão no texto');
if (r.modo === 'auto' && /(reembols|estorn|cr[eé]dito|desconto|ressarc|indeniz|garantimos|garantido)/i.test(rascunho)) {
  alertas.push('promessa financeira ou garantia em resposta automática');
}

let modo = r.modo;
const motivos = [...r.motivos];
if (modo === 'auto' && alertas.length) {
  modo = 'encaminhar';
  motivos.push(`Guardrail bloqueou o envio automático: ${alertas.join('; ')}`);
}

const slaTxt = fmtData(r.sla_limite);
const motivosHtml = motivos.map((m) => `• ${esc(m)}`).join('\n') || '• (nenhum)';
const blocoResumo =
  `<b>${esc(r.protocolo)}</b> · <b>${esc(r.prioridade)}</b> · ${esc(r.categoria)}\n` +
  `👤 ${esc(r.nome)} · ${esc(r.empresa || 'sem empresa cadastrada')} · plano ${esc(r.plano)}\n` +
  `📝 ${esc(r.resumo)}\n` +
  `🏷️ Equipe: ${esc(r.equipe)} · ⏳ SLA até ${esc(slaTxt)}`;

const htmlAprovacao =
  `<div style="font-size:14px;line-height:1.5">` +
  `<p><strong>${esc(r.protocolo)}</strong> · ${esc(r.prioridade)} · ${esc(r.categoria)} · plano ${esc(r.plano)}</p>` +
  `<p><strong>Por que precisa de você:</strong><br>${motivos.map((m) => esc(m)).join('<br>') || '—'}</p>` +
  `<p><strong>Resumo da IA</strong> (confiança ${Number(r.confianca).toFixed(2)}):<br>${esc(r.resumo)}</p>` +
  `<p><strong>Valor citado:</strong> ${esc(brl(r.valor_envolvido_brl))} · <strong>Prazo SLA:</strong> ${esc(slaTxt)}</p>` +
  `<p><strong>Mensagem do cliente</strong> (dados sensíveis mascarados):<br><em>${esc(r.mensagem_mascarada).replace(/\n/g, '<br>')}</em></p>` +
  (alertas.length ? `<p style="color:#b45309"><strong>Atenção:</strong> ${alertas.map((a) => esc(a)).join('; ')}</p>` : '') +
  `<p>Revise o rascunho abaixo, edite se necessário e decida.</p></div>`;

const assuntoEmail = `Re: ${r.assunto} [${r.protocolo}]`;

return {
  json: {
    ...r,
    modo,
    motivos,
    alertas_guardrail: alertas,
    redator_falhou: redatorFalhou,
    rascunho,
    rascunho_html_curto: esc(rascunho.slice(0, 500)) + (rascunho.length > 500 ? '…' : ''),
    sla_txt: slaTxt,
    bloco_resumo: blocoResumo,
    motivos_html: motivosHtml,
    html_aprovacao: htmlAprovacao,
    email_assunto: assuntoEmail,
    email_html: emailHtml({ titulo: `Sobre a sua solicitação: ${r.assunto}`, corpo: paragrafos(rascunho), protocolo: r.protocolo }),
  },
};

// SUPERVISÃO: traduz a resposta do humano (ou a ausência dela = timeout) em um resultado
// explícito. Nada de ação crítica acontece sem passar por aqui com resultado "aprovado".
// ---- utilitários compartilhados (incluídos pelo gerador nos nós Code que precisam) ----
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const paragrafos = (t) => String(t ?? '').trim().split(/\n{2,}/)
  .map((p) => `<p style="margin:0 0 14px">${esc(p).replace(/\n/g, '<br>')}</p>`).join('');
const emailHtml = ({ titulo, corpo, protocolo }) => `<!doctype html><html lang="pt-BR"><body style="margin:0;background:#f3f5f9;font-family:Segoe UI,Helvetica,Arial,sans-serif;color:#1f2937">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:24px 12px"><tr><td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:10px;overflow:hidden;border:1px solid #e3e7ef">
<tr><td style="background:#1d3b8b;color:#ffffff;padding:18px 24px;font-size:17px;font-weight:600">Vértice Cloud · Atendimento</td></tr>
<tr><td style="padding:24px 24px 8px;font-size:15px;line-height:1.55">
<p style="margin:0 0 14px;font-size:17px;font-weight:600">${esc(titulo)}</p>${corpo}</td></tr>
<tr><td style="padding:8px 24px 22px;font-size:12px;color:#6b7280">Protocolo <strong style="color:#1f2937">${esc(protocolo)}</strong> · guarde este número para acompanhar sua solicitação.</td></tr>
</table></td></tr></table></body></html>`;
const fmtData = (iso) => new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const brl = (n) => (n == null || Number.isNaN(Number(n))) ? 'não informado' : Number(n).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const f = $input.item.json;
const st = $('Guardrail').first().json;
const CATS = ['cobranca', 'reembolso', 'cancelamento', 'incidente_tecnico', 'duvida_tecnica', 'comercial', 'elogio_sugestao', 'outros'];
const EQUIPES = {
  cobranca: 'Financeiro', reembolso: 'Financeiro', cancelamento: 'Customer Success', incidente_tecnico: 'Suporte N2 / Plantão',
  duvida_tecnica: 'Suporte N1', comercial: 'Vendas', elogio_sugestao: 'Customer Success', outros: 'Triagem manual',
};

const decisao = f['Decisão'];
let resultado = 'timeout'; // sem resposta dentro do prazo: falha segura, nenhuma ação é executada
if (decisao === 'Aprovar e enviar') resultado = 'aprovado';
else if (decisao === 'Rejeitar e tratar manualmente') resultado = 'rejeitado';

const escolhida = f['Categoria final'];
const categoria_final = CATS.includes(escolhida) ? escolhida : st.categoria;
const respostaForm = String(f['Resposta final'] ?? '').trim();
const resposta_final = respostaForm || st.rascunho;
const norm = (t) => String(t).replace(/\s+/g, ' ').trim();
const editado = norm(resposta_final) !== norm(st.rascunho);

const valorBruto = f['Valor aprovado (R$)'];
const valorForm = valorBruto === undefined || valorBruto === null || String(valorBruto).trim() === '' ? null : Number(valorBruto);
const valor_aprovado = valorForm != null && !Number.isNaN(valorForm) ? valorForm : (st.valor_envolvido_brl ?? null);
const acao_tipo = resultado === 'aprovado' && ['reembolso', 'cancelamento'].includes(categoria_final) ? categoria_final : '';
const aprovador = String(f['Seu nome'] ?? '').trim() || (resultado === 'timeout' ? 'ninguém (timeout)' : 'não informado');

return {
  json: {
    ...st,
    resultado,
    categoria_final,
    categoria_corrigida: categoria_final !== st.categoria,
    equipe_final: EQUIPES[categoria_final] ?? st.equipe,
    resposta_final,
    editado,
    valor_aprovado,
    acao_tipo,
    aprovador,
    obs_humana: String(f['Observação'] ?? '').trim(),
    email_html_final: emailHtml({ titulo: `Sobre a sua solicitação: ${st.assunto}`, corpo: paragrafos(resposta_final), protocolo: st.protocolo }),
  },
};
